<script setup>import {computed} from 'vue';import {useRoute,useRouter} from 'vue-router';const route=useRoute(),router=useRouter();const publicPage=computed(()=>route.meta.public);const menus=[['/dashboard','数据概览','⌁'],['/products','卡商品','◇'],['/activities','活动 Banner','▣'],['/members','会员管理','◎'],['/orders','订单管理','≡'],['/verifications','核销记录','✓'],['/staff','权限账号','♙']];const logout=()=>{localStorage.removeItem('admin_token');router.push('/login')}</script>
<template><router-view v-if="publicPage"/><div v-else class="shell"><aside><div class="brand"><span class="brand-mark">水</span><div><strong>丽水湾</strong><small>运营管理中心</small></div></div><nav><router-link v-for="m in menus" :key="m[0]" :to="m[0]"><span>{{m[2]}}</span>{{m[1]}}</router-link></nav><button class="logout" @click="logout">退出登录</button></aside><main><header><div><b>{{menus.find(m=>m[0]===route.path)?.[1]||'运营中心'}}</b><span>单门店 · 实时数据</span></div><i>生产管理端</i></header><section class="content"><router-view/></section></main></div></template>
